<script setup>
import { ref, computed, onMounted } from 'vue'
import { marked } from 'marked'
import DOMPurify from 'dompurify'
import { BookOpen, Bot, Brain, FileText, GraduationCap, LayoutDashboard, Send, Upload, Sparkles, ClipboardList, Database, RefreshCw, Download, MessageCircle, Menu } from 'lucide-vue-next'
import { api } from './api/client'

const active = ref('chat'), course = ref('大数据与人工智能'), level = ref('初学者')
const messages = ref([{role:'assistant',content:'你好！我是你的 AI 课程学习助手。你可以上传课程 PDF，之后我会优先根据课程资料回答；也可以生成知识点总结、练习题、复习卡片或学习计划。'}])
const input = ref(''), busy = ref(false), status = ref('正在连接后端…'), error = ref('')
const papers = ref([]), datasets = ref([]), reports = ref([]), selectedDataset = ref(''), analysis = ref(null)
const topic = ref(''), materialKind = ref('summary'), material = ref(null)
const rendered = (s)=>DOMPurify.sanitize(marked.parse(s||''))
async function refresh(){ try { await api.health(); status.value='后端已连接'; const [p,d,r]=await Promise.all([api.papers(),api.datasets(),api.reports()]); papers.value=p.items;datasets.value=d.items;reports.value=r.items; if(!selectedDataset.value&&datasets.value.length)selectedDataset.value=datasets.value[0].filename } catch(e){status.value='后端未连接';error.value=e.message} }
onMounted(refresh)
async function send(){ if(!input.value.trim()||busy.value)return; const q=input.value.trim();input.value='';messages.value.push({role:'user',content:q});busy.value=true;error.value='';try{const r=await api.chat(q,course.value);messages.value.push({role:'assistant',content:r.answer,sources:r.sources||[]})}catch(e){error.value=e.message;messages.value.push({role:'assistant',content:'请求失败：'+e.message})}finally{busy.value=false} }
async function uploadPaper(e){const file=e.target.files?.[0];if(!file)return;busy.value=true;error.value='';try{const r=await api.uploadPaper(file);status.value=`已建立知识索引：${r.filename}（${r.chunks} 个文本片段）`;await refresh()}catch(e){error.value=e.message}finally{busy.value=false;e.target.value=''} }
async function uploadDataset(e){const file=e.target.files?.[0];if(!file)return;try{const r=await api.uploadDataset(file);status.value=`已上传 ${r.filename}，共 ${r.rows} 行`;await refresh();selectedDataset.value=r.filename}catch(e){error.value=e.message}finally{e.target.value=''} }
async function makeMaterial(){if(!topic.value.trim())return;busy.value=true;error.value='';try{material.value=await api.material(materialKind.value,topic.value,level.value)}catch(e){error.value=e.message}finally{busy.value=false}}
async function analyze(){if(!selectedDataset.value)return;busy.value=true;error.value='';try{analysis.value=await api.analyze(selectedDataset.value)}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveCurrentReport(){const body=material.value?`# ${material.value.topic}\n\n${material.value.content}`:analysis.value?`# 数据分析报告：${analysis.value.filename}\n\n- 行数：${analysis.value.rows}\n- 列：${analysis.value.columns.join(', ')}\n\n## 描述统计\n\n\`\`\`json\n${JSON.stringify(analysis.value.describe,null,2)}\n\`\`\`\n`:messages.value.slice(-2).map(m=>`## ${m.role==='user'?'问题':'回答'}\n\n${m.content}`).join('\n\n');try{const r=await api.saveReport(topic.value||selectedDataset.value||'学习报告',body);status.value=`报告已保存：${r.filename}`;await refresh()}catch(e){error.value=e.message}}
const currentTitle=computed(()=>({chat:'AI 学习问答',library:'课程知识库',study:'学习材料生成',data:'学习数据分析',reports:'学习报告'}[active.value]))
</script>

<template>
<div class="shell">
  <aside class="sidebar">
    <div class="brand"><div class="brand-icon"><GraduationCap :size="24"/></div><div><strong>知学 AI</strong><small>COURSE LEARNING COPILOT</small></div></div>
    <div class="course-pill"><BookOpen :size="16"/><select v-model="course" aria-label="当前课程"><option>大数据与人工智能</option><option>Python 程序设计</option><option>深度学习基础</option><option>Linux 系统管理</option><option>通用课程</option></select></div>
    <div class="nav-label">学习工作台</div>
    <button v-for="item in [{id:'chat',label:'AI 学习问答',icon:MessageCircle},{id:'library',label:'课程知识库',icon:BookOpen},{id:'study',label:'学习材料生成',icon:Brain},{id:'data',label:'数据练习分析',icon:Database},{id:'reports',label:'学习报告',icon:FileText}]" :key="item.id" class="nav-item" :class="{active:active===item.id}" @click="active=item.id"><component :is="item.icon" :size="18"/><span>{{item.label}}</span><span v-if="item.id==='library'&&papers.length" class="count">{{papers.length}}</span></button>
    <div class="sidebar-bottom"><div class="status-dot" :class="{offline:status==='后端未连接'}"></div><span>{{status}}</span><button title="刷新状态" @click="refresh"><RefreshCw :size="14"/></button></div>
  </aside>
  <main class="main">
    <header class="topbar"><div><div class="eyebrow">YOUR PERSONAL LEARNING SPACE</div><h1>{{currentTitle}}</h1></div><div class="top-actions"><span class="level-label">学习阶段</span><select v-model="level"><option>初学者</option><option>有基础</option><option>进阶学习</option></select><div class="avatar"><GraduationCap :size="18"/></div></div></header>
    <div v-if="error" class="error-banner">{{error}} <button @click="error=''">关闭</button></div>

    <section v-if="active==='chat'" class="content chat-layout">
      <div class="welcome-card"><div class="welcome-copy"><div class="tag"><Sparkles :size="14"/> AI 学习伙伴</div><h2>今天，想学会什么？</h2><p>提问、梳理知识，或把难懂的概念拆解成简单步骤。</p><div class="suggestions"><button v-for="s in ['用简单的例子解释什么是神经网络','帮我总结本章核心知识点','生成 5 道选择题并附答案解析']" :key="s" @click="input=s">{{s}} <span>↗</span></button></div></div><div class="welcome-art"><div class="orb"><Bot :size="58"/></div><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><span class="float-chip chip-one">学习 · 理解 · 掌握</span><span class="float-chip chip-two">AI + 课程知识</span></div></div>
      <div class="chat-panel"><div class="panel-heading"><div><strong>学习对话</strong><small>回答会优先参考已上传的课程资料</small></div><span class="online"><i></i> 助手就绪</span></div><div class="messages" ref="messageBox"><div v-for="(m,i) in messages" :key="i" class="message-row" :class="m.role"><div class="message-avatar"> <Bot v-if="m.role==='assistant'" :size="17"/><span v-else>我</span></div><div class="message-body"><div class="message-name">{{m.role==='assistant'?'知学 AI':'你'}}</div><div class="bubble" v-html="rendered(m.content)"></div><div v-if="m.sources?.length" class="source-list"><span class="source-title">参考课程资料</span><span v-for="(s,j) in m.sources" :key="j" class="source-chip"><FileText :size="12"/> {{s.filename}} · 片段 {{s.chunk_id}}</span></div></div></div><div v-if="busy" class="message-row assistant"><div class="message-avatar"><Bot :size="17"/></div><div class="bubble typing">正在整理思路<span>.</span><span>.</span><span>.</span></div></div></div><form class="composer" @submit.prevent="send"><textarea v-model="input" rows="1" placeholder="输入你的课程问题…（Enter 发送，Shift + Enter 换行）" @keydown.enter.exact.prevent="send"/><button class="send-btn" :disabled="busy||!input.trim()"><Send :size="17"/> 发送</button></form><div class="privacy-note">AI 生成内容可能有误，重要知识点请结合教材与教师讲解核对。</div></div>
    </section>

    <section v-else-if="active==='library'" class="content">
      <div class="section-intro"><div><h2>建立你的课程知识库</h2><p>上传 PDF 教材或讲义，系统将提取文本并建立本地检索索引。</p></div><label class="primary-btn"><Upload :size="16"/> 上传课程 PDF<input type="file" accept="application/pdf,.pdf" hidden @change="uploadPaper"/></label></div>
      <div class="info-strip"><Brain :size="20"/><div><strong>检索增强问答（RAG）</strong><p>提问时会从已索引的资料中检索相关片段。扫描版 PDF 若没有文本层，可能无法提取内容。</p></div></div>
      <div class="panel"><div class="panel-heading"><div><strong>已收录课程资料</strong><small>{{papers.length}} 份资料</small></div></div><div v-if="papers.length" class="file-list"><div v-for="p in papers" :key="p.filename" class="file-row"><div class="file-icon"><FileText :size="20"/></div><div class="file-info"><strong>{{p.filename}}</strong><small>{{p.chunks}} 个文本片段已建立索引</small></div><span class="indexed">已索引</span></div></div><div v-else class="empty-state"><div class="empty-icon"><Upload :size="24"/></div><strong>知识库还是空的</strong><p>上传第一份课程 PDF，开始建立专属学习资料库。</p><label class="secondary-btn">选择 PDF 文件<input type="file" accept="application/pdf,.pdf" hidden @change="uploadPaper"/></label></div></div>
    </section>

    <section v-else-if="active==='study'" class="content study-layout"><div class="panel material-form"><div class="panel-heading"><div><strong>学习材料生成器</strong><small>基于主题与课程知识库创建复习内容</small></div><Sparkles :size="20" class="purple"/></div><label class="field-label">学习主题</label><input v-model="topic" class="text-input" placeholder="例如：卷积神经网络的工作原理"/><label class="field-label">你想生成什么？</label><div class="material-options"><button v-for="o in [{id:'summary',title:'知识点总结',desc:'梳理概念与重点',icon:ClipboardList},{id:'quiz',title:'练习题',desc:'自测并查看解析',icon:Brain},{id:'flashcards',title:'复习卡片',desc:'问答式记忆',icon:BookOpen},{id:'plan',title:'7 天学习计划',desc:'规划学习节奏',icon:LayoutDashboard}]" :key="o.id" :class="{chosen:materialKind===o.id}" @click="materialKind=o.id"><component :is="o.icon" :size="20"/><strong>{{o.title}}</strong><small>{{o.desc}}</small></button></div><button class="primary-btn full" :disabled="busy||!topic.trim()" @click="makeMaterial"><Sparkles :size="16"/> {{busy?'正在生成…':'生成学习材料'}}</button></div><div class="panel output-panel"><div class="panel-heading"><div><strong>生成结果</strong><small>可保存为 Markdown 学习报告</small></div><button v-if="material" class="secondary-btn small-btn" @click="saveCurrentReport"><Download :size="14"/> 保存报告</button></div><div v-if="material" class="markdown-output" v-html="rendered(material.content)"></div><div v-else class="empty-state compact"><div class="empty-icon"><Sparkles :size="22"/></div><strong>你的学习内容将在这里呈现</strong><p>填写主题并选择生成类型即可开始。</p></div></div></section>

    <section v-else-if="active==='data'" class="content"><div class="section-intro"><div><h2>数据练习分析</h2><p>上传课堂练习或成绩 CSV，查看数据规模、缺失值和描述性统计。</p></div><label class="primary-btn"><Upload :size="16"/> 上传 CSV<input type="file" accept=".csv,text/csv" hidden @change="uploadDataset"/></label></div><div class="panel"><div class="panel-heading"><div><strong>我的 CSV 文件</strong><small>当前支持通用 CSV 描述统计</small></div></div><div v-if="datasets.length" class="dataset-controls"><select v-model="selectedDataset"><option v-for="d in datasets" :key="d.filename" :value="d.filename">{{d.filename}}</option></select><button class="primary-btn" :disabled="busy" @click="analyze"><Database :size="16"/> 分析数据</button></div><div v-else class="empty-state"><div class="empty-icon"><Database :size="24"/></div><strong>暂无数据文件</strong><p>上传 CSV 开始分析。</p></div></div><div v-if="analysis" class="analysis-results"><div class="stat-cards"><div class="stat-card"><small>数据行数</small><strong>{{analysis.rows}}</strong></div><div class="stat-card"><small>字段数量</small><strong>{{analysis.columns.length}}</strong></div><div class="stat-card"><small>字段缺失值总数</small><strong>{{Object.values(analysis.missing).reduce((a,b)=>a+b,0)}}</strong></div></div><div class="panel"><div class="panel-heading"><strong>字段信息</strong><button class="secondary-btn small-btn" @click="saveCurrentReport"><Download :size="14"/> 保存分析报告</button></div><div class="table-wrap"><table><thead><tr><th>字段</th><th>缺失值</th><th>类型/统计摘要</th></tr></thead><tbody><tr v-for="col in analysis.columns" :key="col"><td>{{col}}</td><td>{{analysis.missing[col]}}</td><td><code>{{JSON.stringify(analysis.describe[col]||{}).slice(0,180)}}</code></td></tr></tbody></table></div></div></div></section>

    <section v-else class="content"><div class="section-intro"><div><h2>学习报告</h2><p>查看已经保存的总结、练习材料和数据分析报告。</p></div><button class="secondary-btn" @click="refresh"><RefreshCw :size="15"/> 刷新列表</button></div><div class="panel"><div class="panel-heading"><div><strong>已保存的报告</strong><small>{{reports.length}} 份 Markdown 报告</small></div></div><div v-if="reports.length" class="file-list"><div v-for="r in reports" :key="r.filename" class="file-row"><div class="file-icon"><FileText :size="20"/></div><div class="file-info"><strong>{{r.filename}}</strong><small>{{(r.bytes/1024).toFixed(1)}} KB · Markdown</small></div><a class="secondary-btn small-btn" :href="`/api/reports/${encodeURIComponent(r.filename)}`" target="_blank"><Download :size="14"/> 查看/下载</a></div></div><div v-else class="empty-state"><div class="empty-icon"><FileText :size="24"/></div><strong>还没有保存报告</strong><p>生成学习材料或分析 CSV 后，可以将结果保存到这里。</p></div></div></section>
    <footer>知学 AI · 课程学习助手 <span>学习由你主导，AI 为你辅助</span></footer>
  </main>
</div>
</template>
